        const items = await collection
            .find({
                $or: [
                    { meet_id: meetId },
                    { meet_id: meet._id.toString() },
                    { meet_id: meet._id }
                ]
            })
            .sort({ date: -1, created_at: -1 })
            .toArray()

        const formattedItems = items.map((item) => ({
