        }

        const db = await getDb()
        const meetCollection = db.collection('friendship_meets')
        
        // Support both slug and ObjectId lookup for the meet
        let meetQuery: any
        try {
            if (ObjectId.isValid(id)) {
                meetQuery = { _id: new ObjectId(id) }
            } else {
                throw new Error('Not an ObjectId')
            }
        } catch {
            meetQuery = { slug: id }
        }
        
        // Verify meet exists and get its identifier
        const meet = await meetCollection.findOne(meetQuery)
        if (!meet) {
            return NextResponse.json({ success: false, error: 'Friendship meet not found' }, { status: 404 })
        }
        
        // Use slug if available, otherwise use _id string
        const meetId = meet.slug || meet._id.toString()
        
        const galleryCollection = db.collection('gallery_items')

        // Query gallery items by meet_id (handles both string slugs and legacy ObjectId references)
        const items = await galleryCollection
            .find({
                $or: [
                    { meet_id: meetId }, // String match (new format)
                    { meet_id: meet._id } // ObjectId match (legacy format)
                ]
            })
            .sort({ date: -1, created_at: -1 })
            .toArray()

        const formattedItems = items.map((item) => ({
            id: item._id.toString(),
            meet_id: typeof item.meet_id === 'string' ? item.meet_id : item.meet_id.toString(),
            title_en: item.title_en || '',
            title_ta: item.title_ta || '',
            country: item.country || '',
            state: item.state || '',
            district: item.district || '',
            city: item.city || '',
            date: item.date || null,
            description_en: item.description_en || '',
            description_ta: item.description_ta || '',
            image: item.image || null,
            created_at: item.created_at,
        }))

        return NextResponse.json({ success: true, data: formattedItems })
    } catch (error) {
        console.error('GET gallery items error:', error)
        return NextResponse.json({ success: false, error: 'Failed to fetch gallery items' }, { status: 500 })
    }
}

import { NextResponse } from 'next/server'
import { getDb } from '@/lib/mongodb'
import { ObjectId } from 'mongodb'

// Helper to generate URL-friendly slug from location and year
function generateSlug(district: string, state: string, country: string, year: number): string {
    const normalize = (str: string) => 
        str.toLowerCase()
           .replace(/[^a-z0-9]+/g, '-')
           .replace(/^-+|-+$/g, '')
    
    const parts = [normalize(district), normalize(state), normalize(country), year.toString()]
    return parts.filter(Boolean).join('-')
}

// Helper to ensure unique slug
async function ensureUniqueSlug(db: any, baseSlug: string, excludeId?: ObjectId): Promise<string> {
    const collection = db.collection('friendship_meets')
    let slug = baseSlug
    let counter = 1
    
    while (true) {
        const query: any = { slug }
        if (excludeId) query._id = { $ne: excludeId }
        
        const existing = await collection.findOne(query)
        if (!existing) return slug
        
        slug = `${baseSlug}-${counter}`
        counter++
    }
}

export async function GET(request: Request) {
    try {
        const { searchParams } = new URL(request.url)
        const country = searchParams.get('country')
        const state = searchParams.get('state')
        const district = searchParams.get('district')
        const year = searchParams.get('year')

        const db = await getDb()
        const collection = db.collection('friendship_meets')

        const filter: any = {}
        if (country && country !== 'All') filter.country = country
        if (state && state !== 'All') filter.state = state
        if (district && district !== 'All') filter.district = district
        if (year && year !== 'All') filter.year = parseInt(year)

        const meets = await collection
            .find(filter)
            .sort({ year: -1, created_at: -1 })
            .toArray()

        // Auto-migrate: Add slugs to records that don't have them
        const updates = []
        for (const meet of meets) {
            if (!meet.slug) {
                const baseSlug = generateSlug(meet.district, meet.state, meet.country, meet.year)
                const slug = await ensureUniqueSlug(db, baseSlug, meet._id)
                updates.push(
                    collection.updateOne(
                        { _id: meet._id },
                        { $set: { slug, updated_at: new Date() } }
                    )
                )
                meet.slug = slug // Update in memory for response
            }
        }
        if (updates.length > 0) {
            await Promise.all(updates)
        }

        const formattedMeets = meets.map((meet) => ({
            id: meet.slug || meet._id.toString(),
            country: meet.country,
            state: meet.state,
            district: meet.district,
            year: meet.year,
            caption_en: meet.caption_en || '',
            caption_ta: meet.caption_ta || '',
            banner_image: meet.banner_image || null,
        }))

        return NextResponse.json({ success: true, data: formattedMeets })
    } catch (error) {
        console.error('GET friendship meets error:', error)
        return NextResponse.json({ success: false, error: 'Failed to fetch friendship meets' }, { status: 500 })
    }
}

