}

'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Image from 'next/image'
import Link from 'next/link'
import { HandHeart, MapPin, Calendar, ArrowLeft, Loader2 } from 'lucide-react'
import { useTranslation } from '@/contexts/TranslationContext'
import type { HumanitarianService } from '@/types/api'

export default function HumanitarianServiceDetail() {
    const params = useParams()
    const router = useRouter()
    const { t, lang } = useTranslation()
    const [service, setService] = useState<HumanitarianService | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState(false)

    useEffect(() => {
        async function loadService() {
            try {
                const res = await fetch(`/api/services/${params.id}`)
                const data = await res.json()
                if (data.success && data.data) {
                    setService(data.data)
                } else {
                    setError(true)
                }
            } catch (err) {
                console.error('Failed to load service:', err)
                setError(true)
            } finally {
                setLoading(false)
            }
        }

        if (params.id) {
            loadService()
        }
    }, [params.id])

    if (loading) {
        return (
            <div className="min-h-screen bg-neutral-50 flex items-center justify-center">
                <Loader2 className="w-10 h-10 animate-spin text-primary-700" />
            </div>
        )
    }

    if (error || !service) {
        return (
            <div className="min-h-screen bg-neutral-50 flex items-center justify-center px-4">
                <div className="text-center">
                    <h1 className="text-3xl font-bold text-neutral-900 mb-4">Service Not Found</h1>
                    <p className="text-neutral-600 mb-6">The humanitarian service you're looking for doesn't exist.</p>
                    <Link
                        href="/humanitarian-services"
                        className="inline-flex items-center gap-2 bg-primary-700 text-white px-6 py-3 rounded-lg hover:bg-primary-800 transition"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Back to Services
                    </Link>
                </div>
            </div>
        )
    }

    return (
        <div className="bg-neutral-50 min-h-screen">
            {/* Back Button */}
            <div className="bg-white border-b border-neutral-200">
                <div className="container-custom mx-auto px-4 py-4">
                    <Link
                        href="/humanitarian-services"
                        className="inline-flex items-center gap-2 text-neutral-600 hover:text-primary-700 transition font-medium"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Back to All Services
                    </Link>
                </div>
            </div>

            {/* Hero Image */}
            <section className="relative bg-white">
                <div className="container-custom mx-auto px-4 py-8">
                    <div className="relative aspect-[21/9] w-full rounded-2xl overflow-hidden shadow-2xl bg-neutral-100">
                        <Image
                            src={service.image_url}
                            alt={lang === 'ta' ? service.title_ta : service.title_en}
                            fill
                            sizes="(max-width: 1280px) 100vw, 1280px"
                            className="object-contain bg-neutral-100"
                            priority
                        />
                    </div>
                </div>
            </section>

            {/* Content */}
            <section className="py-12">
                <div className="container-custom mx-auto px-4">
                    <div className="max-w-4xl mx-auto">
                        {/* Title */}
                        <div className="mb-8">
                            <div className="inline-flex items-center gap-2 bg-primary-100 px-4 py-2 rounded-full mb-4">
                                <HandHeart className="w-5 h-5 text-primary-700" />
                                <span className="text-primary-700 font-medium text-sm">Humanitarian Service</span>
                            </div>
                            <h1 className="text-3xl md:text-4xl font-bold text-neutral-900 leading-tight">
                                {lang === 'ta' && service.title_ta ? service.title_ta : service.title_en}
                            </h1>
                        </div>

                        {/* Meta Info */}
                        <div className="bg-white rounded-2xl shadow-md p-6 mb-8 border border-neutral-200">
                            <div className="flex flex-wrap gap-6">
                                <div className="flex items-center gap-3">
                                    <div className="bg-primary-100 p-3 rounded-xl">
                                        <Calendar className="w-6 h-6 text-primary-700" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-neutral-500 uppercase tracking-wide mb-0.5">Date</p>
                                        <p className="text-neutral-900 font-semibold">
                                            {new Date(service.date).toLocaleDateString('en-US', {
                                                month: 'long',
                                                day: 'numeric',
                                                year: 'numeric'
                                            })}
                                        </p>
                                    </div>
                                </div>

                                <div className="flex items-center gap-3">
                                    <div className="bg-primary-100 p-3 rounded-xl">
                                        <MapPin className="w-6 h-6 text-primary-700" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-neutral-500 uppercase tracking-wide mb-0.5">Location</p>
                                        <p className="text-neutral-900 font-semibold">
                                            {[service.city, service.district, service.state, service.country].filter(Boolean).join(', ')}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Description */}
                        <div className="bg-white rounded-2xl shadow-md p-8 border border-neutral-200">
                            <h2 className="text-2xl font-bold text-neutral-900 mb-6">About This Service</h2>
                            <div
                                className="prose prose-lg max-w-none text-neutral-700 leading-relaxed"
                                dangerouslySetInnerHTML={{
                                    __html: lang === 'ta' && service.description_ta
                                        ? service.description_ta
                                        : service.description_en
                                }}
                            />
                        </div>

                        {/* CTA */}
                        <div className="mt-8 text-center">
                            <Link
                                href="/humanitarian-services"
                                className="inline-flex items-center gap-2 bg-neutral-100 text-neutral-700 hover:bg-neutral-200 px-8 py-3 rounded-lg font-medium transition"
                            >
                                <ArrowLeft className="w-4 h-4" />
                                View More Services
                            </Link>
                        </div>
                    </div>
                </div>
            </section>
        </div>
    )
}

'use client'

import React, { useState, useEffect } from 'react'
import Image from 'next/image'
import { useTranslation } from '@/contexts/TranslationContext'
import { Users, Shield, Loader2, Mail, Linkedin, Phone } from 'lucide-react'
import { getTeam } from '@/lib/api'
import type { TeamMember } from '@/types/api'

type Person = {
    name: string
    role: string
    img: string
    email?: string
    linkedin?: string
    link?: string
    phone?: string
}

const Card: React.FC<{ person: Person }> = ({ person }) => {
    const handleClick = () => {
        if (person.link) {
            window.location.href = person.link
        }
    }

    return (
        <div
            className={`group bg-white rounded-2xl p-6 shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-1 border border-neutral-100 text-center relative overflow-hidden ${person.link ? 'cursor-pointer' : ''}`}
            onClick={handleClick}
        >
            <div className="absolute top-0 left-0 w-full h-1 bg-linear-to-r from-red-600 to-red-800 transform scale-x-0 group-hover:scale-x-100 transition-transform duration-300" />

            <div className="w-56 h-56 mx-auto mb-4 rounded-xl p-1.5 bg-linear-to-br from-red-100 to-red-50 group-hover:from-red-600 group-hover:to-red-800 transition-colors duration-300">
                <div className="w-full h-full rounded-lg overflow-hidden bg-white relative">
                    <Image
                        src={person.img}
                        alt={`${person.name} photo`}
                        fill
                        className="object-cover transition-transform duration-500 group-hover:scale-110"
                        sizes="224px"
                    />
                </div>
            </div>

            <h3 className="text-lg font-bold text-neutral-900 mb-1">{person.name}</h3>
            <p className="text-red-700 font-medium mb-4 text-sm">{person.role}</p>

            <div className="flex items-center justify-center gap-3">
                {(person.linkedin || person.email || ((person.role === 'President' || person.role === 'Founder, President') && person.phone)) ? (
                    <>
                        {person.linkedin && (
                            <a
                                href={person.linkedin}
                                target="_blank"
                                rel="noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="w-10 h-10 rounded-full bg-neutral-50 hover:bg-blue-600 text-neutral-600 hover:text-white flex items-center justify-center transition-all duration-300 shadow-sm hover:shadow-md"
                                aria-label="LinkedIn"
                            >
                                <Linkedin className="w-4 h-4" />
                            </a>
                        )}
                        {person.email && (
                            <a
                                href={
                                    `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(
                                        person.email
                                    )}`
                                }
                                target="_blank"
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="w-10 h-10 rounded-full bg-neutral-50 hover:bg-red-700 text-neutral-600 hover:text-white flex items-center justify-center transition-all duration-300 shadow-sm hover:shadow-md"
                                aria-label="Email"
                            >
                                <Mail className="w-4 h-4" />
                            </a>
                        )}
                        {person.phone && (person.role === 'President' || person.role === 'Founder, President') && (
                            <a
                                href={`tel:${person.phone.replace(/\s+/g, '')}`}
                                onClick={(e) => e.stopPropagation()}
                                className="w-10 h-10 rounded-full bg-neutral-50 hover:bg-emerald-600 text-neutral-600 hover:text-white flex items-center justify-center transition-all duration-300 shadow-sm hover:shadow-md"
                                aria-label="Phone"
                            >
                                <Phone className="w-4 h-4" />
                            </a>
                        )}
                    </>
                ) : (
                    <span className="h-10" /> // Spacer to keep height consistent if no links
                )}
            </div>
            {person.phone && (person.role === 'President' || person.role === 'Founder, President') && (
                <p className="text-neutral-600 text-sm mt-2">{person.phone}</p>
            )}
        </div>
    )
}

export default function OurTeam() {
    const { t } = useTranslation()
    const [presidents, setPresidents] = useState<TeamMember[]>([])
    const [trustees, setTrustees] = useState<TeamMember[]>([])
    const [membersByLevel, setMembersByLevel] = useState<any[]>([])
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        async function loadTeam() {
            try {
                const response = await getTeam()
                if (response.success && response.data) {
                    // Maintain backward compatibility
                    setPresidents(response.data.presidents)
                    setTrustees(response.data.trustees)

                    // Use new hierarchical structure
                    setMembersByLevel(response.data.membersByLevel || [])
                }
            } catch (error) {
                console.error('Failed to load team:', error)
            } finally {
                setLoading(false)
            }
        }
        loadTeam()
    }, [])

    // Convert API data to Person format
    const mapToPerson = (member: TeamMember): Person => ({
        name: member.name,
        role: member.role,
        img: member.image_url,
        email: member.email || '',
        phone: member.phone || '',
    })

    return (
        <div className="bg-neutral-50 min-h-screen">
            {/* Hero */}
            <section className="relative bg-transparent pt-12 md:pt-16 lg:pt-20 pb-8 border-b border-neutral-100 overflow-hidden" style={{ minHeight: '320px' }}>
                <div className="absolute inset-0 z-0 pointer-events-none">
                    <Image
                        src="/Images/iplbanner.png"
                        alt="Our team background"
                        fill
                        className="opacity-40 object-contain"
                        style={{ objectPosition: 'center' }}
                        priority
                    />
                    <div style={{ position: 'absolute', inset: 0, backgroundColor: 'rgba(0,0,0,0.04)' }} />
                </div>
                <div className="relative z-10 container-custom mx-auto text-center max-w-4xl">
                    <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-red-50 border border-red-100 mb-6 animate-fade-in">
                        <Users className="w-4 h-4 text-red-700" />
                        <span className="text-sm font-semibold text-red-800">{t('ourteam.badge', 'Leadership & Volunteers')}</span>
                    </div>

                    <h1 className="text-4xl md:text-5xl lg:text-6xl font-extrabold text-neutral-900 mb-6 animate-slide-up">
                        {t('ourteam.title', 'Our Team')}
                    </h1>

                    <p className="text-xl text-neutral-600 leading-relaxed max-w-2xl mx-auto animate-slide-up" style={{ animationDelay: '0.1s' }}>
                        {t('ourteam.subtitle', 'The people who nurture the spirit of Love, Friendship, and Humanity')}
                    </p>
                </div>
            </section>

            {loading ? (
                <div className="flex justify-center items-center py-20">
                    <Loader2 className="w-8 h-8 animate-spin text-red-700" />
                </div>
            ) : (
                <>
                    {/* Group Photo Section */}
                    <section className="py-12 border-b border-neutral-100 bg-white">
                        <div className="container-custom mx-auto px-4">
                            <div className="max-w-5xl mx-auto">
                                <div className="relative aspect-video w-full rounded-2xl overflow-hidden shadow-lg border border-neutral-100 bg-[#FFFACD]">
                                    <Image
                                        src="/Images/our-tea,m.jpg"
                                        alt="IPL Team Group Photo"
                                        fill
                                        className="object-contain"
                                        priority
                                    />
                                </div>
                            </div>
                        </div>
                    </section>

                    {/* Display members dynamically based on Hierarchy Level from Admin */}
                    {(() => {
                        // 1. Sort groups by level ensures we follow Admin Hierarchy
                        const sortedGroups = [...membersByLevel].sort((a, b) => a.level - b.level)

                        // Helper for pluralization
                        const getRoleTitle = (role: string, count: number) => {
                            if (count <= 1) return role === 'Coordinator' ? 'Co-ordinator' : role
                            if (role === 'Coordinator') return 'Co-ordinators'
                            if (role.endsWith('y')) return role.slice(0, -1) + 'ies'
                            return role + 's'
                        }

                        // Helper: Normalize role names for matching
                        const isRole = (group: any, baseName: string) => {
                            if (!group) return false
                            const name = group.roleName || ''
                            if (baseName === 'President') return name === 'President' || name === 'Founder, President'
                            if (baseName === 'Board') return name === 'Board of Trustee' || name === 'Board of Trustees'
                            return name === baseName
                        }

                        // Helper to render a standard section
                        const renderStandardSection = (group: any) => {
                            const { roleName, members, level } = group
                            if (!members || members.length === 0) return null

                            const displayRole = getRoleTitle(roleName, members.length)
                            const isExecutive = level <= 3
                            // Board is usually Grid layout
                            const isBoard = isRole(group, 'Board')

                            return (
                                <section
                                    key={roleName}
                                    className="py-12 border-b border-neutral-100"
                                    style={{
                                        background: isExecutive
                                            ? 'linear-gradient(135deg, rgba(220, 38, 38, 0.05) 0%, rgba(239, 68, 68, 0.02) 100%)'
                                            : 'transparent'
                                    }}
                                >
                                    <div className="container-custom mx-auto">
                                        <div className="text-center mb-10">
                                            <div className="flex items-center justify-center gap-3 mb-3">
                                                <Shield className={`w-6 h-6 ${isExecutive ? 'text-red-700' : 'text-red-600'}`} />
                                                <h2 className={`text-3xl font-bold ${isExecutive ? 'text-red-800' : 'text-neutral-900'}`}>
                                                    {displayRole}
                                                </h2>
                                            </div>
                                        </div>

                                        <div className={`grid gap-6 justify-items-center ${members.length === 1 ? 'sm:grid-cols-1 max-w-sm mx-auto' :
                                            isBoard ? 'sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4' :
                                                members.length <= 2 ? 'sm:grid-cols-1 md:grid-cols-2 max-w-2xl mx-auto' :
                                                    'sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4'
                                            }`}>
                                            {members.map((member: TeamMember, i: number) => (
                                                <div
                                                    key={member.id}
                                                    className="animate-slide-up"
                                                    style={{ animationDelay: `${i * 100}ms` }}
                                                >
                                                    <Card person={mapToPerson(member)} />
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </section>
                            )
                        }

                        // Helper for Side-by-Side Sections
                        const renderSideBySideSection = (group1: any, group2: any, bgColor: string) => {
                            // Identify which is which to enforce Left/Right alignment preference
                            // We prefer Gen Sec LEFT, Treasurer RIGHT
                            // We prefer VP LEFT, Joint Sec RIGHT

                            let leftGroup = group1
                            let rightGroup = group2

                            const isGenSec = (g: any) => isRole(g, 'General Secretary')
                            const isTreasurer = (g: any) => isRole(g, 'Treasurer')
                            const isVP = (g: any) => isRole(g, 'Vice President')

                            // Swap if needed to match visual preference
                            if (isTreasurer(leftGroup) && isGenSec(rightGroup)) { leftGroup = group2; rightGroup = group1 }
                            if (!isVP(leftGroup) && isVP(rightGroup)) { leftGroup = group2; rightGroup = group1 }

                            // Determine grid layout (Uneven for VP to allow side-by-side)
                            const hasVP = isVP(leftGroup) || isVP(rightGroup)
                            const gridCols = hasVP ? 'grid-cols-1 lg:grid-cols-5' : 'grid-cols-1 md:grid-cols-2'
                            const leftSpan = hasVP ? (isVP(leftGroup) ? 'lg:col-span-3' : 'lg:col-span-2') : ''
                            const rightSpan = hasVP ? (isVP(rightGroup) ? 'lg:col-span-3' : 'lg:col-span-2') : ''
                            const gap = hasVP ? 'gap-8' : 'gap-12 lg:gap-24'

                            return (
                                <section key={`${leftGroup.roleName}-${rightGroup.roleName}`} className={`py-12 border-b border-neutral-100 ${bgColor}`}>
                                    <div className="container-custom mx-auto">
                                        <div className={`grid ${gridCols} ${gap} items-start`}>
                                            {/* Left Column */}
                                            <div className={`flex flex-col items-center w-full ${leftSpan}`}>
                                                <div className="flex items-center justify-center gap-3 mb-8">
                                                    <Shield className="w-6 h-6 text-purple-700" />
                                                    <h2 className="text-3xl font-bold text-purple-900">{getRoleTitle(leftGroup.roleName, leftGroup.members.length)}</h2>
                                                </div>
                                                <div className={`w-full flex flex-wrap justify-center gap-6 ${!hasVP && leftGroup.members.length === 1 ? 'max-w-sm' : ''}`}>
                                                    {leftGroup.members.map((member: TeamMember) => (
                                                        <div key={member.id} className="flex justify-center">
                                                            <Card person={mapToPerson(member)} />
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>

                                            {/* Right Column */}
                                            <div className={`flex flex-col items-center w-full ${rightSpan}`}>
                                                <div className="flex items-center justify-center gap-3 mb-8">
                                                    <Shield className="w-6 h-6 text-purple-700" />
                                                    <h2 className="text-3xl font-bold text-purple-900">{getRoleTitle(rightGroup.roleName, rightGroup.members.length)}</h2>
                                                </div>
                                                <div className={`w-full flex flex-wrap justify-center gap-6 ${!hasVP && rightGroup.members.length === 1 ? 'max-w-sm' : ''}`}>
                                                    {rightGroup.members.map((member: TeamMember) => (
                                                        <div key={member.id} className="flex justify-center">
                                                            <Card person={mapToPerson(member)} />
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </section>
                            )
                        }

                        // Iteration Logic
                        const renderedSections = []
                        for (let i = 0; i < sortedGroups.length; i++) {
                            const group = sortedGroups[i]
                            const nextGroup = sortedGroups[i + 1]

                            // Check for Pair 1: Gen Sec + Treasurer
                            const isGenSecPair = (isRole(group, 'General Secretary') && nextGroup && isRole(nextGroup, 'Treasurer')) ||
                                (isRole(group, 'Treasurer') && nextGroup && isRole(nextGroup, 'General Secretary'))

                            // Check for Pair 2: Vice President + Joint Secretary - DISABLED for now to allow full width
                            /* const isVPPair = (isRole(group, 'Vice President') && nextGroup && isRole(nextGroup, 'Joint Secretary')) ||
                                (isRole(group, 'Joint Secretary') && nextGroup && isRole(nextGroup, 'Vice President')) */
                            const isVPPair = false

                            if (isGenSecPair) {
                                renderedSections.push(renderSideBySideSection(group, nextGroup, 'bg-linear-to-b from-red-50/30 to-white'))
                                i++ // Skip next
                            } else if (isVPPair) {
                                renderedSections.push(renderSideBySideSection(group, nextGroup, 'bg-white'))
                                i++ // Skip next
                            } else {
                                renderedSections.push(renderStandardSection(group))
                            }
                        }

                        return renderedSections
                    })()}

                    {/* Fallback to legacy display if no hierarchical data */}
                    {membersByLevel.length === 0 && (
                        <>
                            {/* President Section */}
                            {presidents.length > 0 && (
                                <section className="py-12 border-b border-neutral-100">
                                    <div className="container-custom mx-auto">
                                        <div className="text-center mb-10">
                                            <div className="flex items-center justify-center gap-3 mb-3">
                                                <Shield className="w-6 h-6 text-red-700" />
                                                <h2 className="text-3xl font-bold text-neutral-900">Founder,President</h2>
                                            </div>
                                        </div>

                                        <div className="grid gap-6 justify-items-center sm:grid-cols-1 max-w-sm mx-auto">
                                            {presidents.map((member, i) => (
                                                <div key={member.id} className="animate-slide-up" style={{ animationDelay: `${i * 100}ms` }}>
                                                    <Card person={mapToPerson(member)} />
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </section>
                            )}

                            {/* Board of Trustee Section */}
                            {trustees.length > 0 && (
                                <section className="py-12 border-b border-neutral-100">
                                    <div className="container-custom mx-auto">
                                        <div className="text-center mb-10">
                                            <div className="flex items-center justify-center gap-3 mb-3">
                                                <Shield className="w-6 h-6 text-red-700" />
                                                <h2 className="text-3xl font-bold text-neutral-900">Board of Trustee</h2>
                                            </div>
                                        </div>

                                        <div className="grid gap-6 justify-items-center sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4">
                                            {trustees.map((member, i) => (
                                                <div key={member.id} className="animate-slide-up" style={{ animationDelay: `${i * 100}ms` }}>
                                                    <Card person={mapToPerson(member)} />
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </section>
                            )}
                        </>
                    )}

                    {/* Empty State */}
                    {membersByLevel.length === 0 && presidents.length === 0 && trustees.length === 0 && (
                        <section className="py-20 text-center">
                            <Users className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                            <h3 className="text-xl font-semibold text-gray-600 mb-2">Team Coming Soon</h3>
                            <p className="text-gray-500">We're assembling our team of dedicated volunteers.</p>
                        </section>
                    )}
                </>
            )}
        </div>
    )
}

'use client'

import React, { useState, useEffect } from 'react'
import Image from 'next/image'
import Link from 'next/link'
import {
  Heart,
  Users,
  HandHeart,
  Calendar,
  ArrowRight,
  Mail,
  ChevronLeft,
  ChevronRight,
  Sparkles,
  Quote
} from 'lucide-react'
import { useTranslation } from '@/contexts/TranslationContext'
import { getHomeData } from '@/lib/api'
import type { CarouselImage, HumanitarianService } from '@/types/api'

type ImageItem = { src: string; title?: string; subtitle?: string; hideText?: boolean }

const ImageCarousel: React.FC = () => {
  const { t } = useTranslation()
  const [currentIndex, setCurrentIndex] = useState<number>(0)
  const [isTransitioning, setIsTransitioning] = useState<boolean>(false)
  const [images, setImages] = useState<ImageItem[]>([])
  const [loading, setLoading] = useState(true)

  // Fetch carousel images from API
  useEffect(() => {
    async function loadCarouselImages() {
      try {
        const response = await getHomeData()
        if (response.success && response.data) {
          // Map API data to ImageItem format
          const carouselImages: ImageItem[] = response.data.carousel.map((item: CarouselImage) => ({
            src: item.image_url,
            title: item.title || '',
            subtitle: item.subtitle || '',
            hideText: !!Number(item.hide_text)
          }))
          setImages(carouselImages)
        }
      } catch (error) {
        console.error('Failed to load carousel:', error)
      } finally {
        setLoading(false)
      }
    }
    loadCarouselImages()
  }, [])

  const changeIndex = (nextIndex: number) => {
    if (isTransitioning) return
    setIsTransitioning(true)
    setCurrentIndex(nextIndex)
    setTimeout(() => setIsTransitioning(false), 500)
  }

  const goToPrevious = () => {
    const next = currentIndex === 0 ? images.length - 1 : currentIndex - 1
    changeIndex(next)
  }

  const goToNext = () => {
    const next = currentIndex === images.length - 1 ? 0 : currentIndex + 1
    changeIndex(next)
  }

  // Auto-advance carousel
  useEffect(() => {
    if (images.length === 0) return
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev === images.length - 1 ? 0 : prev + 1))
    }, 2000)
    return () => clearInterval(timer)
  }, [images.length])

  if (loading || images.length === 0) {
    return (
      <div className="relative h-[280px] sm:h-[360px] md:h-[420px] lg:h-[520px] w-full overflow-hidden rounded-xl md:rounded-2xl shadow-2xl bg-neutral-200 animate-pulse" />
    )
  }

  return (
    <div className="relative h-[280px] sm:h-[360px] md:h-[420px] lg:h-[520px] w-full overflow-hidden rounded-xl md:rounded-2xl shadow-2xl group bg-[#FFFACD]">
      {images.map((img, index) => (
        <div
          key={index}
          className={`absolute inset-0 transition-opacity duration-500 ease-in-out ${index === currentIndex ? 'opacity-100' : 'opacity-0'
            }`}
        >

          <Image
            src={img.src}
            alt={img.title || 'IPL Carousel'}
            fill
            sizes="100vw"
            className="object-contain"
            priority={index === 0}
          />
          {!img.hideText && (img.title || img.subtitle) && (
            <div className="absolute bottom-0 left-0 right-0 p-4 sm:p-6 md:p-8 z-20 text-neutral-900 transform transition-all duration-500 translate-y-0">
              {img.title && (
                <h3 className="text-xl sm:text-2xl md:text-3xl lg:text-4xl font-bold mb-2 sm:mb-3 drop-shadow-sm">
                  {img.title}
                </h3>
              )}
              {img.subtitle && (
                <p className="text-sm sm:text-base md:text-lg text-neutral-700 max-w-2xl drop-shadow-sm line-clamp-2 sm:line-clamp-none">
                  {img.subtitle}
                </p>
              )}
            </div>
          )}
        </div>
      ))}

      {/* Navigation Buttons */}
      <button
        onClick={goToPrevious}
        className="absolute left-2 sm:left-4 top-1/2 -translate-y-1/2 z-30 p-2 sm:p-3 rounded-full bg-black/10 backdrop-blur-md text-neutral-800 border border-black/10 hover:bg-[#d50032] hover:text-white transition-all opacity-50 sm:opacity-0 group-hover:opacity-100 sm:-translate-x-4 sm:group-hover:translate-x-0"
      >
        <ChevronLeft className="w-5 h-5 sm:w-6 sm:h-6" />
      </button>
      <button
        onClick={goToNext}
        className="absolute right-2 sm:right-4 top-1/2 -translate-y-1/2 z-30 p-2 sm:p-3 rounded-full bg-black/10 backdrop-blur-md text-neutral-800 border border-black/10 hover:bg-[#d50032] hover:text-white transition-all opacity-50 sm:opacity-0 group-hover:opacity-100 sm:translate-x-4 sm:group-hover:translate-x-0"
      >
        <ChevronRight className="w-5 h-5 sm:w-6 sm:h-6" />
      </button>

      {/* Indicators */}
      <div className="absolute bottom-6 right-6 z-30 flex gap-2">
        {images.map((_, index) => (
          <button
            key={index}
            onClick={() => changeIndex(index)}
            className={`h-2 rounded-full transition-all duration-300 ${index === currentIndex ? 'w-8 bg-red-600' : 'w-2 bg-neutral-300 hover:bg-neutral-500'
              }`}
          />
        ))}
      </div>
    </div>
  )
}

const RecentActivitiesCarousel: React.FC = () => {
  const { lang, t } = useTranslation()
  const [currentIndex, setCurrentIndex] = useState(0)
  const [itemsPerPage, setItemsPerPage] = useState(3)
  const [services, setServices] = useState<HumanitarianService[]>([])
  const [loading, setLoading] = useState(true)

  // Helper to strip HTML tags for preview
  const stripHtml = (html: string) => {
    if (!html) return ''
    return html.replace(/<[^>]*>/g, '').substring(0, 150)
  }

  // Fetch latest services from API
  useEffect(() => {
    async function loadServices() {
      try {
        const response = await getHomeData()
        if (response.success && response.data) {
          setServices(response.data.services)
        }
      } catch (error) {
        console.error('Failed to load services:', error)
      } finally {
        setLoading(false)
      }
    }
    loadServices()
  }, [])

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) setItemsPerPage(1)
      else if (window.innerWidth < 1024) setItemsPerPage(2)
      else setItemsPerPage(3)
    }
    handleResize()
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  // Auto-slide functionality
  useEffect(() => {
    if (services.length === 0) return
    const timer = setInterval(() => {
      setCurrentIndex(prev => {
        const maxIndex = Math.max(0, services.length - itemsPerPage)
        return prev >= maxIndex ? 0 : prev + 1
      })
    }, 5000)
    return () => clearInterval(timer)
  }, [itemsPerPage, services.length])

  const maxIndex = Math.max(0, services.length - itemsPerPage)

  const nextSlide = () => {
    setCurrentIndex(prev => (prev >= maxIndex ? 0 : prev + 1))
  }

  const prevSlide = () => {
    setCurrentIndex(prev => (prev === 0 ? maxIndex : prev - 1))
  }

  if (loading) {
    return <div className="animate-pulse bg-neutral-200 h-64 rounded-2xl" />
  }

  return (
    <div className="relative group/carousel">
      {/* Controls - Left Button */}
      <button
        onClick={prevSlide}
        className="absolute left-0 top-1/2 -translate-y-1/2 z-30 p-3 rounded-full bg-white shadow-lg border border-neutral-100 text-neutral-700 hover:bg-neutral-50 hover:text-red-700 transition-all opacity-100 md:opacity-0 md:group-hover/carousel:opacity-100 md:-translate-x-4 md:group-hover/carousel:translate-x-0"
        aria-label="Previous"
      >
        <ChevronLeft className="w-5 h-5" />
      </button>

      {/* Controls - Right Button */}
      <button
        onClick={nextSlide}
        className="absolute right-0 top-1/2 -translate-y-1/2 z-30 p-3 rounded-full bg-white shadow-lg border border-neutral-100 text-neutral-700 hover:bg-neutral-50 hover:text-red-700 transition-all opacity-100 md:opacity-0 md:group-hover/carousel:opacity-100 md:translate-x-4 md:group-hover/carousel:translate-x-0"
        aria-label="Next"
      >
        <ChevronRight className="w-5 h-5" />
      </button>

      <div className="overflow-hidden -mx-4 px-4 py-4">
        <div
          className="flex gap-8 transition-transform duration-500 ease-out"
          style={{ transform: `translateX(-${currentIndex * (100 / itemsPerPage)}%)` }}
        >
          {services.map((service) => (
            <Link
              key={service.id}
              href={`/humanitarian-services/${service.id}`}
              className="flex-none w-full md:w-[calc(50%-16px)] lg:w-[calc(33.333%-21.33px)] group bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 hover:-translate-y-1 block"
            >
              <div className="h-48 overflow-hidden relative">
                <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-colors z-10" />
                <Image
                  src={service.image_url}
                  alt={lang === 'ta' ? service.title_ta : service.title_en}
                  fill
                  sizes="(max-width: 768px) 100vw, (max-width: 1024px) 50vw, 33vw"
                  className="object-contain bg-neutral-100"
                />
                <div className="absolute top-4 right-4 z-20 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-xs font-bold text-red-700 uppercase tracking-wider shadow-sm">
                  {new Date(service.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                </div>
              </div>
              <div className="p-6">
                <h3 className="text-xl font-bold text-neutral-900 mb-2 group-hover:text-red-700 transition-colors line-clamp-2">
                  {lang === 'ta' ? service.title_ta : service.title_en}
                </h3>
                <div className="flex items-center gap-1.5 text-neutral-500 text-sm mb-3">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                  </svg>
                  {[service.city, service.district, service.state, service.country].filter(Boolean).join(', ')}
                </div>
                <p className="text-neutral-600 text-sm leading-relaxed line-clamp-3 mb-4">
                  {stripHtml(lang === 'ta' ? service.description_ta : service.description_en)}
                </p>
                <div className="flex items-center justify-start mt-auto">
                  <span className="text-red-700 text-sm font-semibold flex items-center gap-1 group-hover:gap-2 transition-all">
                    {String(t('home.read_more', 'Read more'))} <ArrowRight className="w-4 h-4" />
                  </span>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </div>
  )
}

