'use client'

import React, { useState } from 'react'
import { X, Bell, Loader2 } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'

interface NotifyMeModalProps {
    isOpen: boolean
    onClose: () => void
    eventDetails: {
        id: string
        title: string
        date: string | Date
        location?: string
    }
}

export default function NotifyMeModal({ isOpen, onClose, eventDetails }: NotifyMeModalProps) {
    const [email, setEmail] = useState('')
    const [loading, setLoading] = useState(false)
    const [message, setMessage] = useState<{ text: string, type: 'success' | 'error' } | null>(null)

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        setMessage(null)

        try {
            const res = await fetch('/api/notify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email,
                    eventId: eventDetails.id,
                    eventTitle: eventDetails.title,
                    eventDate: eventDetails.date,
                    eventLocation: eventDetails.location,
                }),
            })

            const data = await res.json()

            if (res.ok) {
                setMessage({ text: 'Reminder set successfully!', type: 'success' })
                setEmail('')
                setTimeout(() => {
                    onClose()
                    setMessage(null)
                }, 2000)
            } else {
                setMessage({ text: data.error || 'Failed to set reminder.', type: 'error' })
            }
        } catch (error) {
            setMessage({ text: 'Something went wrong. Please try again.', type: 'error' })
        }
        setLoading(false)
    }

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    {/* Backdrop */}
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 bg-black/50 z-50 backdrop-blur-sm"
                    />

                    {/* Modal */}
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 pointer-events-none">
                        <motion.div
                            initial={{ scale: 0.95, opacity: 0, y: 20 }}
                            animate={{ scale: 1, opacity: 1, y: 0 }}
                            exit={{ scale: 0.95, opacity: 0, y: 20 }}
                            className="bg-white rounded-2xl shadow-xl w-full max-w-md pointer-events-auto overflow-hidden"
                        >
                            {/* Header */}
                            <div className="bg-red-600 px-6 py-4 flex justify-between items-center text-white">
                                <h3 className="font-bold text-lg flex items-center gap-2">
                                    <Bell className="w-5 h-5" />
                                    Get Notified
                                </h3>
                                <button
                                    onClick={onClose}
                                    className="p-1 hover:bg-white/20 rounded-full transition-colors"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </div>

                            {/* Content */}
                            <div className="p-6">
                                <p className="text-gray-600 mb-4">
                                    Enter your email to receive reminders for:
                                    <br />
                                    <strong className="text-gray-900">{eventDetails.title}</strong>
                                </p>
                                <p className="text-xs text-gray-500 mb-6">
                                    We'll notify you 1 day before and a few hours before the event starts.
                                </p>

                                <form onSubmit={handleSubmit} className="space-y-4">
                                    <div>
                                        <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
                                            Email Address
                                        </label>
                                        <input
                                            type="email"
                                            id="email"
                                            required
                                            value={email}
                                            onChange={(e) => setEmail(e.target.value)}
                                            placeholder="you@example.com"
                                            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-red-500 outline-none transition-all"
                                        />
                                    </div>

                                    {message && (
                                        <div className={`p-3 rounded-lg text-sm ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                                            {message.text}
                                        </div>
                                    )}

                                    <button
                                        type="submit"
                                        disabled={loading}
                                        className="w-full bg-red-600 text-white py-2.5 rounded-lg font-semibold hover:bg-red-700 transition disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center gap-2"
                                    >
                                        {loading ? (
                                            <>
                                                <Loader2 className="w-4 h-4 animate-spin" />
                                                Setting Reminder...
                                            </>
                                        ) : (
                                            'Notify Me'
                                        )}
                                    </button>
                                </form>
                            </div>
                        </motion.div>
                    </div>
                </>
            )}
        </AnimatePresence>
    )
}

'use client'

import { useEditor, EditorContent } from '@tiptap/react'
import { Extension } from '@tiptap/core'
import StarterKit from '@tiptap/starter-kit'
import Underline from '@tiptap/extension-underline'
import { TextStyle } from '@tiptap/extension-text-style'
import { Color } from '@tiptap/extension-color'
import { FontFamily } from '@tiptap/extension-font-family'
import { Bold, Italic, Underline as UnderlineIcon, List, ListOrdered, Undo, Redo, Palette } from 'lucide-react'
import { useState, useEffect, useRef } from 'react'

interface RichTextEditorProps {
  value: string
  onChange: (value: string) => void
  placeholder?: string
}

const COLORS = [
  { name: 'Black', value: '#000000' },
  { name: 'Red', value: '#EF4444' },
  { name: 'Orange', value: '#F97316' },
  { name: 'Yellow', value: '#EAB308' },
  { name: 'Green', value: '#22C55E' },
  { name: 'Blue', value: '#3B82F6' },
  { name: 'Indigo', value: '#6366F1' },
  { name: 'Purple', value: '#A855F7' },
  { name: 'Pink', value: '#EC4899' },
  { name: 'Gray', value: '#6B7280' },
]

const FontSize = Extension.create({
  name: 'fontSize',
  addOptions() {
    return {
      types: ['textStyle'],
    }
  },
  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          fontSize: {
            default: null,
            parseHTML: (element: HTMLElement) => element.style.fontSize || null,
            renderHTML: (attributes: { fontSize?: string | null }) => {
              if (!attributes.fontSize) return {}
              return { style: `font-size: ${attributes.fontSize}` }
            },
          },
        },
      },
    ]
  },
  addCommands() {
    return {
      setFontSize:
        (fontSize: string) =>
        ({ chain }: { chain: () => any }) =>
          chain().setMark('textStyle', { fontSize }).run(),
      unsetFontSize:
        () =>
        ({ chain }: { chain: () => any }) =>
          chain().setMark('textStyle', { fontSize: null }).run(),
    } as any
  },
})

export default function RichTextEditor({ value, onChange, placeholder }: RichTextEditorProps) {
  const [showColorPicker, setShowColorPicker] = useState(false)
  const colorPickerRef = useRef<HTMLDivElement>(null)
  
  // Close color picker when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (colorPickerRef.current && !colorPickerRef.current.contains(event.target as Node)) {
        setShowColorPicker(false)
      }
    }
    
    if (showColorPicker) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [showColorPicker])
  
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: {
          levels: [1, 2, 3],
        },
      }),
      Underline,
      TextStyle,
      Color,
      FontFamily.configure({
        types: ['textStyle'],
      }),
      FontSize,
    ],
    content: value,
    immediatelyRender: false,
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML())
    },
    editorProps: {
      attributes: {
        class: 'prose prose-sm max-w-none p-4 border-t min-h-[200px] focus:outline-none',
        spellcheck: 'false',
      },
    },
  })

  if (!editor) return null

  // Get current heading level
  const getCurrentHeading = () => {
    if (editor.isActive('heading', { level: 1 })) return 'h1'
    if (editor.isActive('heading', { level: 2 })) return 'h2'
    if (editor.isActive('heading', { level: 3 })) return 'h3'
    return 'normal'
  }

  return (
    <div className="border rounded-lg overflow-hidden relative">
      <div className="bg-gray-50 border-b p-2 flex flex-wrap gap-1 items-center relative">
        {/* Text Formatting */}
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().toggleBold().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            editor.isActive('bold') ? 'bg-gray-300 text-blue-600' : ''
          }`}
          title="Bold (Ctrl+B)"
        >
          <Bold size={16} />
        </button>
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().toggleItalic().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            editor.isActive('italic') ? 'bg-gray-300 text-blue-600' : ''
          }`}
          title="Italic (Ctrl+I)"
        >
          <Italic size={16} />
        </button>
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().toggleUnderline().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            editor.isActive('underline') ? 'bg-gray-300 text-blue-600' : ''
          }`}
          title="Underline (Ctrl+U)"
        >
          <UnderlineIcon size={16} />
        </button>
        
        <div className="w-px bg-gray-300 mx-1 h-6" />
        
        {/* Lists */}
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().toggleBulletList().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            editor.isActive('bulletList') ? 'bg-gray-300 text-blue-600' : ''
          }`}
          title="Bullet List"
        >
          <List size={16} />
        </button>
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().toggleOrderedList().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            editor.isActive('orderedList') ? 'bg-gray-300 text-blue-600' : ''
          }`}
          title="Ordered List"
        >
          <ListOrdered size={16} />
        </button>
        
        <div className="w-px bg-gray-300 mx-1 h-6" />
        
        {/* Font Family */}
        <select
          value={editor.getAttributes('textStyle').fontFamily || 'default'}
          onChange={(e) => {
            if (e.target.value === 'default') {
              editor.chain().focus().unsetFontFamily().run()
            } else {
              editor.chain().focus().setFontFamily(e.target.value).run()
            }
          }}
          className="px-2 py-1 rounded border bg-white text-sm max-w-[120px]"
          title="Font Family"
        >
          <option value="default">Default</option>
          <option value="Arial">Arial</option>
          <option value="Georgia">Georgia</option>
          <option value="Times New Roman">Times</option>
          <option value="Courier New">Courier</option>
          <option value="Verdana">Verdana</option>
          <option value="Tahoma">Tahoma</option>
        </select>
        
        {/* Heading Styles */}
        <select
          value={getCurrentHeading()}
          onChange={(e) => {
            const value = e.target.value
            if (value === 'normal') {
              editor.chain().focus().setParagraph().run()
            } else if (value === 'h1') {
              editor.chain().focus().setHeading({ level: 1 }).run()
            } else if (value === 'h2') {
              editor.chain().focus().setHeading({ level: 2 }).run()
            } else if (value === 'h3') {
              editor.chain().focus().setHeading({ level: 3 }).run()
            }
          }}
          className="px-2 py-1 rounded border bg-white text-sm"
          title="Text Style"
        >
          <option value="normal">Normal</option>
          <option value="h1">Heading 1</option>
          <option value="h2">Heading 2</option>
          <option value="h3">Heading 3</option>
        </select>

        {/* Font Size */}
        <select
          value={editor.getAttributes('textStyle').fontSize || 'default'}
          onChange={(e) => {
            if (e.target.value === 'default') {
              ;(editor.chain().focus() as any).unsetFontSize().run()
            } else {
              ;(editor.chain().focus() as any).setFontSize(e.target.value).run()
            }
          }}
          className="px-2 py-1 rounded border bg-white text-sm"
          title="Font Size"
        >
          <option value="default">Default</option>
          <option value="12px">12</option>
          <option value="14px">14</option>
          <option value="16px">16</option>
          <option value="18px">18</option>
          <option value="20px">20</option>
          <option value="24px">24</option>
          <option value="28px">28</option>
          <option value="32px">32</option>
        </select>
        
        {/* Color Picker */}
        <div className="relative" ref={colorPickerRef}>
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault()
              setShowColorPicker(!showColorPicker)
            }}
            className={`p-2 rounded hover:bg-gray-200 transition ${
              showColorPicker ? 'bg-gray-300' : ''
            }`}
            title="Text Color"
          >
            <Palette size={16} />
          </button>
          {showColorPicker && (
            <div className="absolute top-full left-0 mt-1 bg-white border rounded-lg shadow-xl p-3 z-100 min-w-[200px]">
              <div className="text-xs font-semibold mb-2 text-gray-700">Text Color</div>
              <div className="grid grid-cols-5 gap-2">
                {COLORS.map((color) => (
                  <button
                    key={color.value}
                    type="button"
                    onClick={(e) => {
                      e.preventDefault()
                      editor.chain().focus().setColor(color.value).run()
                      setShowColorPicker(false)
                    }}
                    className="w-8 h-8 rounded border-2 border-gray-300 hover:border-blue-500 hover:scale-110 transition-all"
                    style={{ backgroundColor: color.value }}
                    title={color.name}
                  />
                ))}
              </div>
              <button
                type="button"
                onClick={(e) => {
                  e.preventDefault()
                  editor.chain().focus().unsetColor().run()
                  setShowColorPicker(false)
                }}
                className="w-full mt-3 text-xs py-1.5 px-2 bg-gray-100 hover:bg-gray-200 rounded transition"
              >
                Reset Color
              </button>
            </div>
          )}
        </div>
        
        <div className="w-px bg-gray-300 mx-1 h-6" />
        
        {/* Undo/Redo */}
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().undo().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            !editor.can().undo() ? 'opacity-50 cursor-not-allowed' : ''
          }`}
          title="Undo (Ctrl+Z)"
          disabled={!editor.can().undo()}
        >
          <Undo size={16} />
        </button>
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault()
            editor.chain().focus().redo().run()
          }}
          className={`p-2 rounded hover:bg-gray-200 transition ${
            !editor.can().redo() ? 'opacity-50 cursor-not-allowed' : ''
          }`}
          title="Redo (Ctrl+Y)"
          disabled={!editor.can().redo()}
        >
          <Redo size={16} />
        </button>
      </div>
      <EditorContent editor={editor} />
      {placeholder && !editor.getHTML() && (
        <p className="absolute top-12 left-4 text-gray-400 pointer-events-none">{placeholder}</p>
      )}
    </div>
  )
}

'use client'

import { FormEvent, useCallback, useEffect, useState } from 'react'
import RichTextEditor from '@/components/RichTextEditor'

interface HistorySectionItem {
    id: string
    section_title_en: string
    section_title_ta: string
    content_en: string
    content_ta: string
    order_index: number
    is_deletable: boolean
}

export default function HistorySection() {
    const [items, setItems] = useState<HistorySectionItem[]>([])
    const [loading, setLoading] = useState(true)
    const [showModal, setShowModal] = useState(false)
    const [editing, setEditing] = useState<HistorySectionItem | null>(null)
    const [submitting, setSubmitting] = useState(false)
    const [message, setMessage] = useState<{ text: string; type: 'success' | 'error' }>({ text: '', type: 'success' })

    const [formData, setFormData] = useState({
        section_title_en: '',
        section_title_ta: '',
        content_en: '',
        content_ta: '',
    })

    const fetchItems = useCallback(async () => {
        try {
            const res = await fetch('/api/admin/history')
            const data = await res.json()
            if (data.success) setItems(data.data)
        } catch {
            setMessage({ text: 'Failed to load history sections', type: 'error' })
        } finally {
            setLoading(false)
        }
    }, [])

    useEffect(() => { fetchItems() }, [fetchItems])

    const openAddModal = () => {
        setEditing(null)
        setFormData({
            section_title_en: '',
            section_title_ta: '',
            content_en: '',
            content_ta: '',
        })
        setShowModal(true)
    }

    const openEditModal = (item: HistorySectionItem) => {
        setEditing(item)
        setFormData({
            section_title_en: item.section_title_en || '',
            section_title_ta: item.section_title_ta || '',
            content_en: item.content_en || '',
            content_ta: item.content_ta || '',
        })
        setShowModal(true)
    }

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault()
        setSubmitting(true)
        try {
            const payload = {
                ...formData,
                ...(editing ? { id: editing.id } : {}),
            }
            const res = await fetch('/api/admin/history', {
                method: editing ? 'PUT' : 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
            })
            const data = await res.json()
            if (data.success) {
                setMessage({ text: editing ? 'History section updated!' : 'History section added!', type: 'success' })
                setShowModal(false)
                setEditing(null)
                fetchItems()
            } else {
                setMessage({ text: data.error || 'Failed', type: 'error' })
            }
        } catch {
            setMessage({ text: 'Failed', type: 'error' })
        } finally {
            setSubmitting(false)
        }
    }

    const handleDelete = async (id: string) => {
        if (!confirm('Delete this history section?')) return
        try {
            const res = await fetch('/api/admin/history', {
                method: 'DELETE',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id }),
            })
            const data = await res.json()
            if (!data.success) throw new Error(data.error || 'Delete failed')
            setMessage({ text: 'History section deleted', type: 'success' })
            fetchItems()
        } catch {
            setMessage({ text: 'Delete failed', type: 'error' })
        }
    }

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-3xl font-bold text-gray-900">History Page</h2>
                <button onClick={openAddModal} className="bg-red-600 text-white px-5 py-2.5 rounded-lg hover:bg-red-700 transition font-medium text-sm">
                    + Add Section
                </button>
            </div>

            {!!message.text && (
                <div className={`mb-4 p-3 rounded-lg text-sm font-medium ${message.type === 'success' ? 'bg-green-50 text-green-800 border border-green-200' : 'bg-red-50 text-red-800 border border-red-200'}`}>
                    {message.text}
                </div>
            )}

            <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 text-xs text-blue-800 mb-5">
                The "Major Milestones" timeline stays hardcoded on the website. These sections appear above it.
            </div>

            {loading ? <p className="text-gray-500">Loading...</p> : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {items.map(item => (
                        <div key={item.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">
                            <div className="flex items-start justify-between mb-3">
                                <div>
                                    <h3 className="text-lg font-bold text-gray-900">{item.section_title_en || 'Untitled Section'}</h3>
                                    {item.section_title_ta && <p className="text-sm text-gray-500">{item.section_title_ta}</p>}
                                </div>
                                <span className="text-xs px-2 py-1 rounded bg-gray-100 text-gray-600">#{item.order_index}</span>
                            </div>
                            <p className="text-sm text-gray-600 line-clamp-3 mb-4">{item.content_en?.replace(/<[^>]*>/g, '').substring(0, 220)}...</p>
                            <div className="flex gap-2">
                                <button onClick={() => openEditModal(item)} className="flex-1 bg-blue-600 text-white py-2 rounded-lg text-sm hover:bg-blue-700 transition">Edit</button>
                                <button
                                    onClick={() => handleDelete(item.id)}
                                    disabled={item.is_deletable === false}
                                    className="flex-1 bg-red-600 text-white py-2 rounded-lg text-sm hover:bg-red-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    Delete
                                </button>
                            </div>
                        </div>
                    ))}
                    {items.length === 0 && <p className="text-gray-500 text-center py-8 col-span-full">No history sections yet.</p>}
                </div>
            )}

            {showModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="flex justify-between items-center p-6 pb-4 border-b">
                            <h3 className="text-xl font-bold text-gray-900">{editing ? 'Edit History Section' : 'Add History Section'}</h3>
                            <button onClick={() => { setShowModal(false); setEditing(null) }} className="text-gray-400 hover:text-gray-600 text-2xl">&times;</button>
                        </div>
                        <div className="p-6 pt-4">
                            <form onSubmit={handleSubmit} className="space-y-4">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-2">Paragraph Title (English) - Optional</label>
                                        <input
                                            value={formData.section_title_en}
                                            onChange={(e) => setFormData({ ...formData, section_title_en: e.target.value })}
                                            className="w-full border rounded-lg p-2.5"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-2">Title (Tamil)</label>
                                        <input
                                            value={formData.section_title_ta}
                                            onChange={(e) => setFormData({ ...formData, section_title_ta: e.target.value })}
                                            className="w-full border rounded-lg p-2.5"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-2">Paragraph Content (English) *</label>
                                    <RichTextEditor
                                        value={formData.content_en}
                                        onChange={(value) => setFormData({ ...formData, content_en: value })}
                                        placeholder="Write history paragraph in English..."
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium mb-2">Paragraph Content (Tamil)</label>
                                    <RichTextEditor
                                        value={formData.content_ta}
                                        onChange={(value) => setFormData({ ...formData, content_ta: value })}
                                        placeholder="Write history paragraph in Tamil..."
                                    />
                                </div>

                                <button type="submit" disabled={submitting} className="w-full bg-red-600 text-white py-3 rounded-lg hover:bg-red-700 font-semibold transition disabled:opacity-50">
                                    {submitting ? 'Saving...' : editing ? 'Update Section' : 'Add Section'}
                                </button>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}

'use client'

import { FormEvent, useCallback, useEffect, useState } from 'react'
import RichTextEditor from '@/components/RichTextEditor'

interface PresidentBlogItem {
    id: string
    title_en: string
    title_ta: string
    description_en: string
    description_ta: string
    image_url: string
}

export default function PresidentBlogSection() {
    const [items, setItems] = useState<PresidentBlogItem[]>([])
    const [loading, setLoading] = useState(true)
    const [showModal, setShowModal] = useState(false)
    const [editing, setEditing] = useState<PresidentBlogItem | null>(null)
    const [submitting, setSubmitting] = useState(false)
    const [message, setMessage] = useState<{ text: string; type: 'success' | 'error' }>({ text: '', type: 'success' })

    const [formData, setFormData] = useState({
        title_en: '',
        title_ta: '',
        description_en: '',
        description_ta: '',
    })

    const fetchItems = useCallback(async () => {
        try {
            const res = await fetch('/api/admin/president-blog')
            const data = await res.json()
            if (data.success) setItems(data.data)
        } catch {
            setMessage({ text: 'Failed to load blog posts', type: 'error' })
        } finally {
            setLoading(false)
        }
    }, [])

    useEffect(() => { fetchItems() }, [fetchItems])

    const openAddModal = () => {
        setEditing(null)
        setFormData({
            title_en: '',
            title_ta: '',
            description_en: '',
            description_ta: '',
        })
        setShowModal(true)
    }

    const openEditModal = (item: PresidentBlogItem) => {
        setEditing(item)
        setFormData({
            title_en: item.title_en || '',
            title_ta: item.title_ta || '',
            description_en: item.description_en || '',
            description_ta: item.description_ta || '',
        })
        setShowModal(true)
    }

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault()
        setSubmitting(true)

        const submitData = new FormData()
        Object.entries(formData).forEach(([key, value]) => submitData.append(key, value))
        const fileInput = e.currentTarget.querySelector('input[type="file"]') as HTMLInputElement
        if (fileInput?.files?.[0]) submitData.append('image', fileInput.files[0])
        if (editing) submitData.append('id', editing.id)

        try {
            const res = await fetch('/api/admin/president-blog', { method: editing ? 'PUT' : 'POST', body: submitData })
            const data = await res.json()
            if (data.success) {
                setMessage({ text: editing ? 'Blog updated!' : 'Blog added!', type: 'success' })
                setShowModal(false)
                setEditing(null)
                fetchItems()
            } else {
                // Show detailed validation error if available
                let errorMessage = data.error
                if (data.details) {
                    const fieldErrors = Object.entries(data.details)
                        .filter(([key]) => key !== '_errors')
                        .map(([key, val]: [string, any]) => val._errors && val._errors.length > 0 ? `${key}: ${val._errors.join(', ')}` : null)
                        .filter(Boolean)
                    if (fieldErrors.length > 0) errorMessage = fieldErrors.join(' | ')
                }
                setMessage({ text: errorMessage || 'Failed', type: 'error' })
            }
        } catch {
            setMessage({ text: 'Failed', type: 'error' })
        } finally {
            setSubmitting(false)
        }
    }

    const handleDelete = async (id: string) => {
        if (!confirm('Delete this blog post?')) return
        try {
            await fetch('/api/admin/president-blog', {
                method: 'DELETE',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id }),
            })
            setMessage({ text: 'Blog deleted', type: 'success' })
            fetchItems()
        } catch {
            setMessage({ text: 'Delete failed', type: 'error' })
        }
    }

    // ÔöÇÔöÇÔöÇ Drag and Drop Handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const [draggedId, setDraggedId] = useState<string | null>(null)

    const handleDragStart = (id: string) => {
        setDraggedId(id)
    }

    const handleDragEnter = (targetId: string) => {
        if (!draggedId || draggedId === targetId) return

        const draggedIndex = items.findIndex(item => item.id === draggedId)
        const targetIndex = items.findIndex(item => item.id === targetId)

        if (draggedIndex === -1 || targetIndex === -1) return

        const newItems = [...items]
        const [removed] = newItems.splice(draggedIndex, 1)
        newItems.splice(targetIndex, 0, removed)

        setItems(newItems)
    }

    const handleDragEnd = async () => {
        setDraggedId(null)
        try {
            await fetch('/api/admin/president-blog', {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ orderedIds: items.map(i => i.id) })
            })
            setMessage({ text: 'Order saved', type: 'success' })
        } catch {
            setMessage({ text: 'Failed to save order', type: 'error' })
        }
    }

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-3xl font-bold text-gray-900">IPL President&apos;s Blog</h2>
                    <p className="text-sm text-gray-500 mt-1">Ôåò Drag cards to reorder posts</p>
                </div>
                <button onClick={openAddModal} className="bg-red-600 text-white px-5 py-2.5 rounded-lg hover:bg-red-700 transition font-medium text-sm">
                    + Add Blog
                </button>
            </div>

            {!!message.text && (
                <div className={`mb-4 p-3 rounded-lg text-sm font-medium ${message.type === 'success' ? 'bg-green-50 text-green-800 border border-green-200' : 'bg-red-50 text-red-800 border border-red-200'}`}>
                    {message.text}
                </div>
            )}

            {loading ? <p className="text-gray-500">Loading...</p> : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {items.map(item => (
                        <div
                            key={item.id}
                            className={`bg-white rounded-xl shadow overflow-hidden transition-all duration-200 cursor-move ${draggedId === item.id ? 'opacity-50 scale-95 ring-2 ring-red-500' : 'hover:-translate-y-1 hover:shadow-lg'}`}
                            draggable
                            onDragStart={() => handleDragStart(item.id)}
                            onDragEnter={() => handleDragEnter(item.id)}
                            onDragEnd={handleDragEnd}
                            onDragOver={(e) => e.preventDefault()}
                        >
                            <img src={item.image_url} alt={item.title_en} className="w-full h-48 object-cover pointer-events-none" />
                            <div className="p-4">
                                <h3 className="font-bold text-gray-900 mb-2 line-clamp-1">{item.title_en}</h3>
                                <p className="text-sm text-gray-600 line-clamp-3 mb-4">{item.description_en?.replace(/<[^>]*>/g, '')}</p>
                                <div className="flex gap-2">
                                    <button onClick={(e) => { e.stopPropagation(); openEditModal(item) }} className="flex-1 bg-blue-600 text-white py-2 rounded-lg text-sm hover:bg-blue-700 transition">Edit</button>
                                    <button onClick={(e) => { e.stopPropagation(); handleDelete(item.id) }} className="flex-1 bg-red-600 text-white py-2 rounded-lg text-sm hover:bg-red-700 transition">Delete</button>
                                </div>
                            </div>
                        </div>
                    ))}
                    {items.length === 0 && <p className="text-gray-500 text-center py-8 col-span-full">No blog posts yet.</p>}
                </div>
            )}

            {showModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-xl max-w-3xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="flex justify-between items-center p-6 pb-4 border-b">
                            <h3 className="text-xl font-bold text-gray-900">{editing ? 'Edit Blog Post' : 'Add Blog Post'}</h3>
                            <button onClick={() => { setShowModal(false); setEditing(null) }} className="text-gray-400 hover:text-gray-600 text-2xl">&times;</button>
                        </div>
                        <div className="p-6 pt-4">
                            <form onSubmit={handleSubmit} className="space-y-4">
                                <div className="rounded-lg border border-gray-200 p-3 bg-gray-50">
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wider mb-2">Section 1</p>
                                    <h4 className="font-semibold text-gray-900">Post Titles</h4>
                                    <p className="text-xs text-gray-600">Add title in English and Tamil (Tamil optional).</p>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-1">Title (English)</label>
                                        <input value={formData.title_en} onChange={(e) => setFormData({ ...formData, title_en: e.target.value })} placeholder="Enter title" className="w-full border rounded-lg p-2.5" />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1">Title (Tamil)</label>
                                        <input value={formData.title_ta} onChange={(e) => setFormData({ ...formData, title_ta: e.target.value })} placeholder="Enter title (Tamil)" className="w-full border rounded-lg p-2.5" />
                                    </div>
                                </div>

                                <div className="rounded-lg border border-gray-200 p-3 bg-gray-50">
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wider mb-2">Section 2</p>
                                    <h4 className="font-semibold text-gray-900">Featured Image</h4>
                                    <p className="text-xs text-gray-600">Upload one image for this post.</p>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <input type="file" name="image" accept="image/*" {...(!editing && { required: true })} className="border rounded-lg p-2.5" />
                                </div>

                                <div className="rounded-lg border border-gray-200 p-3 bg-gray-50">
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wider mb-2">Section 3</p>
                                    <h4 className="font-semibold text-gray-900">Post Description</h4>
                                    <p className="text-xs text-gray-600">Use formatting tools for bold, italic, color, font, headings, and font size.</p>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium mb-2">Description (English)</label>
                                    <RichTextEditor
                                        value={formData.description_en}
                                        onChange={(value) => setFormData({ ...formData, description_en: value })}
                                        placeholder="Write blog description in English..."
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium mb-2">Description (Tamil)</label>
                                    <RichTextEditor
                                        value={formData.description_ta}
                                        onChange={(value) => setFormData({ ...formData, description_ta: value })}
                                        placeholder="Write blog description in Tamil..."
                                    />
                                </div>
                                <button type="submit" disabled={submitting} className="w-full bg-red-600 text-white py-3 rounded-lg hover:bg-red-700 font-semibold transition disabled:opacity-50">
                                    {submitting ? 'Saving...' : editing ? 'Update Blog Post' : 'Add Blog Post'}
                                </button>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useRef, useState, Suspense } from 'react'
import { Search, MapPin } from 'lucide-react'
import { useRouter } from 'next/navigation'
import { useTranslation } from '@/contexts/TranslationContext'

interface GlobalSearchProps {
  className?: string
  placeholder?: string
  autoFocus?: boolean
  onSelect?: (href: string, title: string) => void
  variant?: 'default' | 'hero' | 'mobile'
}

const GlobalSearchInner: React.FC<GlobalSearchProps> = ({
  className = '',
  placeholder,
  autoFocus = false,
  onSelect,
  variant = 'default'
}) => {
  const { t } = useTranslation()
  const router = useRouter()
  const initial = ''
  const [query, setQuery] = useState(initial)
  const [open, setOpen] = useState(false)
  const [activeIndex, setActiveIndex] = useState(-1)
  const [suggestions, setSuggestions] = useState<Array<{ title: string; subtitle?: string; href: string }>>([])
  const containerRef = useRef<HTMLDivElement | null>(null)
  const inputRef = useRef<HTMLInputElement | null>(null)

  useEffect(() => { if (autoFocus && inputRef.current) inputRef.current.focus() }, [autoFocus])

  useEffect(() => {
    const q = query.trim()
    if (!q) {
      setSuggestions([])
      return
    }
    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(q)}&limit=8`)
        const data = await res.json()
        if (data.success && Array.isArray(data.data)) {
          setSuggestions(data.data)
        } else {
          setSuggestions([])
        }
      } catch {
        setSuggestions([])
      }
    }, 180)
    return () => clearTimeout(timer)
  }, [query])

  const commitSearch = useCallback((value: string) => {
    const val = value.trim()
    if (!val) {
      setOpen(false)
      setActiveIndex(-1)
      return
    }
    if (suggestions.length > 0) {
      router.push(suggestions[0].href)
    } else {
      router.push(`/news-events?search=${encodeURIComponent(val)}`)
    }
    setOpen(false)
    setActiveIndex(-1)
  }, [router, suggestions])

  const handleSelect = useCallback((href: string, title: string) => {
    // Navigate directly to the selected page
    if (onSelect) {
      onSelect(href, title)
    }
    router.push(href)
    setQuery('')
    setOpen(false)
    setActiveIndex(-1)
  }, [onSelect, router])

  useEffect(() => {
    const onClickAway = (e: MouseEvent) => {
      if (!containerRef.current) return
      if (!containerRef.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', onClickAway)
    return () => document.removeEventListener('mousedown', onClickAway)
  }, [])

  const highlight = useCallback((text: string) => {
    const qLower = query.toLowerCase()
    const idx = text.toLowerCase().indexOf(qLower)
    if (idx === -1 || !query) return text
    return (
      <>
        {text.slice(0, idx)}<mark className="bg-red-100 text-red-700 rounded px-0.5">{text.slice(idx, idx + query.length)}</mark>{text.slice(idx + query.length)}
      </>
    )
  }, [query])

  const baseInputClasses = variant === 'mobile'
    ? 'w-full pl-11 pr-4 py-3 rounded-xl bg-red-700/40 text-white placeholder-white/70 border border-white/10 hover:border-white/20 focus:ring-2 focus:ring-white/40 outline-none'
    : variant === 'hero'
      ? 'w-full pl-11 pr-4 py-3 rounded-full bg-white border border-neutral-200 shadow-sm focus:border-red-600 focus:ring-2 focus:ring-red-100 outline-none text-sm transition'
      : 'w-56 xl:w-64 pl-9 pr-10 py-2.5 rounded-full bg-white/10 border border-white/20 text-sm text-white placeholder-white/70 hover:border-white/30 focus:bg-white/15 focus:ring-2 focus:ring-white/30 focus:border-white/40 shadow-sm transition-all outline-none'

  return (
    <div ref={containerRef} className={`relative ${className}`}>
      <Search className={`absolute ${variant === 'mobile' ? 'left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-white/70' : variant === 'hero' ? 'left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-neutral-400' : 'left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-white/70'} pointer-events-none`} />
      <input
        ref={inputRef}
        value={query}
        onChange={e => { 
          const newValue = e.target.value
          setQuery(newValue)
          setOpen(newValue.trim().length > 0)
          setActiveIndex(-1)
        }}
        onFocus={() => {
          if (query.trim().length > 0) {
            setOpen(true)
          }
        }}
        onKeyDown={e => {
          if (e.key === 'ArrowDown') {
            e.preventDefault(); setActiveIndex(i => Math.min(suggestions.length - 1, i + 1))
          } else if (e.key === 'ArrowUp') {
            e.preventDefault(); setActiveIndex(i => Math.max(-1, i - 1))
          } else if (e.key === 'Enter') {
            if (activeIndex >= 0 && suggestions[activeIndex]) {
              handleSelect(suggestions[activeIndex].href, suggestions[activeIndex].title)
            } else {
              commitSearch(query)
            }
          } else if (e.key === 'Escape') {
            setOpen(false)
          }
        }}
        placeholder={placeholder || t('search.placeholder', 'Search the site...')}
        className={baseInputClasses}
        autoComplete="off"
      />
      {open && query.trim().length > 0 && (
        <ul className={`absolute left-0 right-0 ${variant === 'mobile' ? 'mt-3' : 'mt-2'} bg-white border border-neutral-200 rounded-xl shadow-2xl overflow-hidden z-[100] text-sm animate-fade-in max-h-96 overflow-y-auto`} role="listbox">
          {suggestions.length > 0 ? (
            suggestions.map((s, i) => (
              <li
                key={s.href + i}
                role="option"
                aria-selected={activeIndex === i}
                tabIndex={-1}
                onMouseDown={e => e.preventDefault()}
                onClick={() => handleSelect(s.href, s.title)}
                className={`px-4 py-3 cursor-pointer flex flex-col gap-0.5 ${activeIndex === i ? 'bg-red-50' : 'hover:bg-neutral-50'}`}
              >
                <span className="font-semibold text-neutral-900 leading-tight">{highlight(s.title)}</span>
                {s.subtitle && (
                  <span className="text-neutral-500 text-xs flex items-center gap-1">
                    <MapPin className="w-3 h-3 text-red-600" /> {highlight(s.subtitle)}
                  </span>
                )}
              </li>
            ))
          ) : (
            <li className="px-4 py-6 text-center text-sm text-neutral-500 flex flex-col gap-2" role="option" aria-selected="false">
              <span className="font-medium text-neutral-700">{t('search.no_results', 'No matches found')}</span>
              <span className="text-xs text-neutral-400">{t('search.suggestions', 'Suggestions')}: {t('search.clear', 'Clear')} / {t('search.popular', 'Popular Searches')}</span>
            </li>
          )}
        </ul>
      )}
    </div>
  )
}

const GlobalSearch: React.FC<GlobalSearchProps> = (props) => {
  return (
    <Suspense fallback={
      <div className={props.className || ''}>
        <div className="relative">
          <input
            type="text"
            placeholder={props.placeholder || 'Search...'}
            disabled
            className="w-full opacity-50"
          />
        </div>
      </div>
    }>
      <GlobalSearchInner {...props} />
    </Suspense>
  )
}

export default GlobalSearch

import { SignJWT, jwtVerify } from 'jose'
import { cookies } from 'next/headers'

const JWT_SECRET = process.env.JWT_SECRET || 'development-secret-change-me-in-prod'
const key = new TextEncoder().encode(JWT_SECRET)

export async function signToken(payload: any): Promise<string> {
    return new SignJWT(payload)
        .setProtectedHeader({ alg: 'HS256' })
        .setIssuedAt()
        .setExpirationTime('4h') // 4 hours expiration
        .sign(key)
}

export async function verifyToken(token: string): Promise<any | null> {
    try {
        const { payload } = await jwtVerify(token, key)
        return payload
    } catch (error) {
        return null
    }
}

export async function getAdminSession() {
    const cookieStore = await cookies()
    const token = cookieStore.get('admin_token')?.value
    if (!token) return null
    return verifyToken(token)
}
